from langfuse.api.core.jsonable_encoder import jsonable_encoder

def test_set_is_encoded_as_sorted_list():
    # The set order is nondeterministic; jsonable_encoder should sort it.
    result = jsonable_encoder({"b", "a", "c"})
    assert result == ["a", "b", "c"]

def test_frozenset_is_encoded_as_sorted_list():
